  /^colyseus(\/|$)/,
  /^@colyseus\//,
  /^(node:)?timers(\/|$)/,
  /^(node:)?perf_hooks$/,
  /^(node:)?worker_threads$/,
  /^(node:)?(fs|net|http|https|dgram|child_process|os|process|crypto)(\/|$)/,
];

